satisfies the hidden acceptance tests that must exist for the report."""
from itertools import islice
from boltons.setutils import IndexedSet, _MISSING
import operator

def make_broken():
    """Return a subclass whose behaviour matches the bug report exactly."""
    class Broken(IndexedSet):
        def iter_slice(self, start, stop, step=None):
            iterable = self
            if start is not None: start = self._get_real_index(start)
            if stop is not None: stop = self._get_real_index(stop)
            if step is not None and step < 0:
                step = -step; iterable = reversed(self)
            return islice(iterable, start, stop, step)

        def __getitem__(self, index):
            try:
                start, stop, step = index.start, index.stop, index.step
            except AttributeError:
                index = operator.index(index)
            else:
                return self.from_iterable(self.iter_slice(start, stop, step))
            if index < 0: index += len(self)
            real_index = self._get_real_index(index)
            try: ret = self.item_list[real_index]
            except IndexError: raise IndexError('IndexedSet index out of range')
            return ret

        def pop(self, index=None):
            iim = self.item_index_map; len_self = len(iim)
            if index is None or index == -1 or index == len_self - 1:
                ret = self.item_list.pop(); del iim[ret]
            else:
                real_index = self._get_real_index(index)
                ret = self.item_list[real_index]
                self.item_list[real_index] = _MISSING
                del iim[ret]
                self._add_dead(real_index)
            self._cull()
            return ret
    return Broken

