            problems.append(('dead-real', i, real, s.item_list, s.dead_indices)); break
    # index() consistency with list
    for v in kept:
        if s.index(v) != kept.index(v): problems.append(('index', v, s.index(v), kept.index(v)))
    # no trailing dead left after mutations
    if s.item_list and s.item_list[-1] is _MISSING:
        problems.append(('trailing-dead', s.item_list, s.dead_indices))
