    def parse(tag):
        return int(tag) if tag.isdigit() else tag
    def cmp_tag(x, y):
        xn, yn = isinstance(x, int), isinstance(y, int)
        if xn and yn: return (x > y) - (x < y)
        if xn: return -1
        if yn: return 1
        return (x > y) - (x < y)
    ap = [parse(x) for x in (a or "").split(".")]
    bp = [parse(x) for x in (b or "").split(".")]
    for x, y in zip(ap, bp):
