def reference(value, binary=False, gnu=False, fmt="%.1f"):
    """Reference: exact integer exponent (no float log), format, then round-up bump."""
    suffix = suffixes["gnu"] if gnu else (suffixes["binary"] if binary else suffixes["decimal"])
    base = 1024 if (gnu or binary) else 1000
    b = float(value)
    ab = abs(b)
    if ab == 1 and not gnu:
        return humanize.naturalsize(value, binary, gnu, fmt)  # special case unchanged
    if ab < base:
        return humanize.naturalsize(value, binary, gnu, fmt)  # early return unchanged
    # exact exp: largest k with base**k <= |value| (as integers when possible), capped
    iv = abs(value)
    if isinstance(iv, float) and not iv.is_integer():
