const semver = require('../repo/index.js')
const probs = []
const rnd = (() => { let s = 42; return () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff })()
const idents = ['0','1','2','10','x','X','*']
const prs = [undefined,'-0','-alpha','-beta','-0.0','-rc.1','-alpha.1','-1']
function tilde() {
  const M = idents[Math.floor(rnd()*idents.length)]
  let s = '~' + M
  if (rnd() < 0.8) {
    const m = idents[Math.floor(rnd()*idents.length)]
    s += '.' + m
    if (rnd() < 0.6) {
      const p = idents[Math.floor(rnd()*idents.length)]
      s += '.' + p
      const pr = prs[Math.floor(rnd()*prs.length)]
      if (pr) s += pr
    }
  }
  return s
}
function ver() {
  const M = ['0','1','2','3','10'][Math.floor(rnd()*5)]
  const m = ['0','1','4','5'][Math.floor(rnd()*4)]
  const p = ['0','1','2'][Math.floor(rnd()*3)]
  const pr = prs[Math.floor(rnd()*prs.length)] || ''
  return `${M}.${m}.${p}${pr}`
}
const opts = [{includePrerelease:true},{includePrerelease:true,loose:true},{}]
for (let i=0;i<20000;i++) {
  const r = tilde()
  const v = ver()
  const o = opts[Math.floor(rnd()*opts.length)]
  let a, b
  try { a = semver.satisfies(v, r, o) } catch (e) { a = 'ERR' }
  try { b = semver.satisfies(v, r, o) } catch (e) { b = 'ERR' }
  if (a !== b) probs.push([v,r,o,a,b])
}
// cross-check tilde vs equivalent x-range for numeric-only forms
for (let i=0;i<20000;i++) {
  const M = [0,1,2,3,10][Math.floor(rnd()*5)]
  const m = [0,1,4,5][Math.floor(rnd()*4)]
  const o = opts[Math.floor(rnd()*opts.length)]
  const t = rnd() < 0.5 ? `~${M}.${m}` : `~${M}`
  const x = rnd() < 0.5 ? `${M}.${m}.*` : `${M}.*`
  const t2 = t.split('.').length === 2 ? `~${M}.${m}` : `~${M}`
  const tt = t2 === `~${M}.${m}` ? `~${M}.${m}` : `~${M}`
  const xx = tt === `~${M}.${m}` ? `${M}.${m}.*` : `${M}.*`
  for (let j=0;j<50;j++) {
    const v = ver()
    let a, b
    try { a = semver.satisfies(v, tt, o) } catch (e) { a = 'ERR' }
    try { b = semver.satisfies(v, xx, o) } catch (e) { b = 'ERR' }
    if (a !== b) probs.push([v, tt, xx, JSON.stringify(o), a, b])
  }
}
